import re


def slugify(text):
    text = text.strip().lower()
    # Replace all non-alphanumeric characters with a single hyphen
    result = re.sub(r"[^a-z0-9]", "-", text)
    # Collapse multiple consecutive hyphens into one and remove trailing hyphens
    return re.sub(r"-+", "", result.rstrip("-"))


def truncate(text, n):
    if len(text) <= n:
        return text
    return text[: n - 3] + "..."
